CREATE TABLE IF NOT EXISTS trips (id UUID PRIMARY KEY, pickup TEXT NOT NULL, dropoff TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE trips ADD COLUMN IF NOT EXISTS completed BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE trips ADD COLUMN IF NOT EXISTS owner_id TEXT NOT NULL DEFAULT 'operator';
CREATE INDEX IF NOT EXISTS trips_owner_created ON trips(owner_id,created_at);
CREATE TABLE IF NOT EXISTS telemetry (event_id UUID PRIMARY KEY, trip_id UUID NOT NULL REFERENCES trips(id), sequence BIGINT NOT NULL, captured_at TIMESTAMPTZ NOT NULL, x DOUBLE PRECISION NOT NULL, y DOUBLE PRECISION NOT NULL, received_at TIMESTAMPTZ NOT NULL, UNIQUE(trip_id,sequence));
CREATE INDEX IF NOT EXISTS telemetry_trip_time ON telemetry(trip_id,captured_at);
